css:
@page {
  size: A4;
  margin: 0;
}

.print-format {
  padding: 0 !important;
  margin: 0 !important;
  margin-top: 0mm !important;
  margin-bottom: 0mm !important;
  margin-left: 0mm !important;
  margin-right: 0mm !important;
  min-height: 0 !important;
  max-width: none !important;
}

.action-banner {
  display: none !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  overflow: hidden !important;
}

.print-format-gutter {
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
}

.print-format-preview {
  padding: 0 !important;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  margin: 0;
  padding: 0;
}

.print-page {
  width: 210mm;
  height: 297mm;
  position: relative;
  overflow: hidden;

  background-image: var(--page-bg);
  background-repeat: no-repeat;
  background-position: center center;
  background-size: 210mm 297mm;

  page-break-after: always;
}

.print-page:last-child {
  page-break-after: auto;
}

.field {
  position: absolute;
  font-size: 10px;
  line-height: 1.25;
  color: #000;
  white-space: normal;
}

.field-customer {
  top: 61mm;
  left: 22mm;
  width: 95mm;
}

.field-customer-name {
  top: 65.5mm;
  left: 22mm;
  width: 95mm;
}

.field-customer-address {
  top: 70mm;
  left: 22mm;
  width: 100mm;
  min-height: 20mm;
}

.field-ref {
  top: 94mm;
  left: 40mm;
  width: 75mm;
}

.field-so-no {
  top: 57.5mm;
  left: 152mm;
  width: 49mm;
}

.field-posting-date {
  top: 70.8mm;
  left: 152mm;
  width: 49mm;
}

.field-delivery-date {
  top: 82mm;
  left: 152mm;
  width: 49mm;
}

.field-sales-person {
  top: 94.5mm;
  left: 152mm;
  width: 49mm;
}

.field-territory {
  top: 101.2mm;
  left: 152mm;
  width: 49mm;
}

.item-table-wrapper {
  position: absolute;
  top: 116mm;
  left: 15mm;
  width: 186mm;
}

.item-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 9px;
  color: #000;
}

.item-table th,
.item-table td {
  border: none;
  padding: 1.5mm;
  vertical-align: top;
  line-height: 1.25;
}

.col-no {
  width: 10mm;
  text-align: center;
}

.col-item {
  width: 76mm;
  text-align: left;
}

.col-qty {
  width: 31mm;
  text-align: right;
}

.col-rate {
  width: 21mm;
  text-align: right;
}

.col-amount {
  width: 22mm;
  text-align: right;
}

.col-shelf {
  width: 26mm;
  text-align: center;
}

.field-total {
  top: 220.5mm;
  left: 156mm;
  width: 40mm;
  text-align: right;
}

.field-discount {
  top: 228.25mm;
  left: 156mm;
  width: 40mm;
  text-align: right;
}

.field-after-discount {
  top: 236mm;
  left: 156mm;
  width: 40mm;
  text-align: right;
}

.field-vat {
  top: 243.75mm;
  left: 156mm;
  width: 40mm;
  text-align: right;
}

.field-grand-total {
  top: 251.5mm;
  left: 156mm;
  width: 40mm;
  text-align: right;
  font-weight: bold;
}

.field-amount-text {
  top: 243mm;
  left: 18mm;
  width: 84mm;
  min-height: 12mm;
}

html:
{% set background = "/assets/connect_diagnostics_core/images/print_formats/sales-order-1.png" %}

{% set sales_persons = [] %}
{% for sp in doc.sales_team %}
  {% if sp.sales_person and sp.sales_person not in sales_persons %}
    {% set _ = sales_persons.append(sp.sales_person) %}
  {% endif %}
{% endfor %}

  <div
    class="print-page"
    style="--page-bg: url('{{ background }}');"
  >

    <!-- Customer -->
    <div class="field field-customer">
      {{ doc.customer or "" }}
    </div>

    <div class="field field-customer-name">
      {{ doc.customer_name or "" }}
    </div>

    <div class="field field-customer-address">
      {{ (doc.address_display or "") | safe }}
    </div>

    <!-- Reference -->
    <div class="field field-ref">
      {{ doc.po_no or "" }}
    </div>

    <!-- Document info -->
    <div class="field field-so-no">
      {{ doc.name }}
    </div>

    <div class="field field-posting-date">
      {{ frappe.format_date(doc.transaction_date, "dd-MM-yyyy") }}
    </div>

    <div class="field field-delivery-date">
      {{ frappe.format_date(doc.delivery_date, "dd-MM-yyyy") if doc.delivery_date else "" }}
    </div>

    <div class="field field-sales-person">
      {{ sales_persons | join(", ") }}
    </div>

    <div class="field field-territory">
      {{ doc.territory or "" }}
    </div>

    <!-- Item table -->
    <div class="item-table-wrapper">
      <table class="item-table">
        <tbody>
          {% for row in doc.items %}
            <tr>
              <td class="col-no">
                {{ loop.index }}
              </td>

              <td class="col-item">
                {{ row.item_code }} : {{ row.item_name }}
              </td>

              <td class="col-qty">
                {{ frappe.format(row.qty, {"fieldtype": "Float"}) }}
              </td>

              <td class="col-rate">
                {{ print_currency(row.rate + (row.discount_amount if row.discount_amount > 0 else 0), doc.currency) }}
              </td>

              <td class="col-amount">
                {{ print_currency(row.amount, doc.currency) }}
              </td>

              <td class="col-shelf"></td>
            </tr>
          {% endfor %}
        </tbody>
      </table>
    </div>

    <!-- Totals -->
    <div class="field field-total">
      {{ print_currency(doc.total or 0, doc.currency) }}
    </div>

    <div class="field field-discount">
      {{ print_currency(doc.discount_amount or 0, doc.currency) }}
    </div>

    <div class="field field-after-discount">
      {{ print_currency(doc.net_total or 0, doc.currency) }}
    </div>

    <div class="field field-vat">
      {{ print_currency(doc.total_taxes_and_charges or 0, doc.currency) }}
    </div>

    <div class="field field-grand-total">
      {{ print_currency(doc.grand_total or 0, doc.currency) }}
    </div>

    <!-- Amount in Thai words -->
    <div class="field field-amount-text">
      ({{ number_to_thai_currency(doc.grand_total or 0, doc.currency) }})
    </div>

  </div>
